LINES = [{'id': 'rule', 'text': 'In this town, every time you say thank you, a cupcake appears in your hands.'}, {'id': 'sweet', 'text': 'I am Pip, I am nine, and I have eaten twelve cupcakes today. Zero guilt.'}, {'id': 'polite', 'text': 'Everybody here is super polite, because polite people are never hungry, and my mama says that is the whole plan.'}, {'id': 'villain', 'text': 'But Bruno hates being nice. He found out you can say thank you to a rock, and it still counts.'}, {'id': 'farm', 'text': 'So he stood by the hydrant and said thank you three hundred times. Boxes of cupcakes everywhere!'}, {'id': 'sell', 'text': 'He sold them for five dollars each, and nobody could say no, because saying no meant saying please.'}, {'id': 'mess', 'text': 'Soon the park was full. Cupcakes on the swings, cupcakes in the fountain, ducks wearing sprinkles like hats.'}, {'id': 'cry', 'text': 'The mayor slipped on frosting, and the town cried. Nobody wanted one more bite, and nobody could stop saying thank you.'}, {'id': 'brave', 'text': 'So I walked right up to Bruno, held out my hands, and said the scariest word I know.'}, {'id': 'sorry', 'text': 'I said, sorry. Sorry that nobody ever gave you a cupcake you did not have to buy yourself.'}, {'id': 'twist', 'text': 'Bruno blinked. Then he whispered thank you, and for the first time ever, a cupcake appeared in his hands.'}, {'id': 'melt', 'text': 'He said it was the first one that tasted like anything. The whole town wanted to hug him.'}, {'id': 'fix', 'text': 'Now Bruno runs the bakery stand, and he only sells to people who say thank you and mean it.'}, {'id': 'end', 'text': 'Mama says thank you is free, but the cupcake is the real price. I say, thank you, Mama!'}]
